  ui_story_40130001_122_dialog_content = "Kalau begitu, mulai sekarang, beri mereka kue dan biskuit.",
  ui_story_40130001_123_dialog_content = "Baik, Tuanku. Selain itu, ini Whimsky yang kamu minta untuknya.",
  ui_story_40130001_124_dialog_content = "Pedas dan penuh cita rasa... Aku tidak punya preferensi untuk itu, tetapi ini adalah sebotol minuman keras yang mantap, tentu saja. Sangat cocok untuknya.",
